CREATE TABLE IF NOT EXISTS "usuario" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(150) NOT NULL,
	"email" VARCHAR(255) NOT NULL UNIQUE,
	"senha_hash" VARCHAR(255) NOT NULL,
	"funcao" VARCHAR(30) NOT NULL,
	"ativo" BOOLEAN NOT NULL,
	"data_cadastro" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "setores" (
	"id_setor" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome_setor" VARCHAR(100) NOT NULL UNIQUE,
	"ativo" BOOLEAN NOT NULL DEFAULT TRUE,
	"data_cadastro" TIMESTAMP,
	PRIMARY KEY("id_setor")
);

CREATE TABLE IF NOT EXISTS "tarefas" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"titulo" VARCHAR(255) NOT NULL,
	"prioridade" VARCHAR(20) NOT NULL,
	"status" VARCHAR(30) NOT NULL,
	"data_criacao" DATE NOT NULL,
	"data_conclusao" DATE NOT NULL,
	"id_setor" INTEGER NOT NULL,
	"id_usuario" INTEGER NOT NULL,
	PRIMARY KEY("id", "id_setor", "id_usuario")
);

ALTER TABLE "tarefas"
ADD FOREIGN KEY("id_setor") REFERENCES "setores"("id_setor")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "usuario"
ADD FOREIGN KEY("id") REFERENCES "tarefas"("id_usuario")
ON UPDATE NO ACTION ON DELETE NO ACTION;